  {
   "codice": "extends RefCounted

signal points_added(amount: int)

var total_points: int = 0

func _on_points_added(amount: int) -> void:
	total_points += amount

func run() -> int:
	points_added.connect(_on_points_added)
	points_added.emit(100)
	points_added.emit(50)
	return total_points
",
   "domanda": "Quanto vale `total_points` alla fine?",
   "spiegazione": "Il segnale viene collegato alla funzione che aggiorna il punteggio. Viene emesso due volte (prima con 100, poi con 50), portando `total_points` a 150."
  },
